query:
UPDATE course_lessons SET content = REPLACE(content,
  'a safety relay or safety PLC. Never wire them directly to a standard standard relay or contactor.',
  'a safety relay or safety PLC. Do not wire them directly to a standard relay or contactor. *(Advanced note: OSSD outputs may be wired directly to safety-rated contactors with force-guided contacts in a redundant configuration with feedback monitoring, achieving Category 3 or 4 architectures without a separate safety relay — but this requires careful design per ISO 13849.)*'
) WHERE id = 120023;

